from typing import Protocol

class Mailer(Protocol):
    def send(self, to: str, body: str) -> None: ...

class UserRepo(Protocol):
    def add(self, email: str) -> int: ...

class SignupService:
    def __init__(self, repo: UserRepo, mailer: Mailer):   # 依赖从外部传入
        self.repo, self.mailer = repo, mailer

    def signup(self, email: str) -> int:
        uid = self.repo.add(email)
        self.mailer.send(email, "欢迎注册")
        return uid

# 测试：注入假实现，不连数据库、不真发邮件
class FakeRepo:
    def __init__(self): self.rows = []
    def add(self, email): self.rows.append(email); return len(self.rows)
class FakeMailer:
    def __init__(self): self.sent = []
    def send(self, to, body): self.sent.append(to)

def test_signup_sends_mail():
    repo, mailer = FakeRepo(), FakeMailer()
    assert SignupService(repo, mailer).signup("a@x.com") == 1
    assert mailer.sent == ["a@x.com"]

// 服务端（Express）：CDN 60 秒新鲜，之后 5 分钟内可先返回旧内容并后台刷新
app.get("/api/articles", async (req, res) => {
  res.set("Cache-Control",
    "public, s-maxage=60, stale-while-revalidate=300, stale-if-error=86400");
  res.json(await listArticles());
});
// 注意：不同 CDN 对 stale-while-revalidate 的支持不同，以各自文档为准

// 前端（React）：先显示缓存数据，同时后台重新请求
import useSWR from "swr";
const fetcher = (url) => fetch(url).then((r) => r.json());

export function ArticleList() {
  const { data, error, isLoading } = useSWR("/api/articles", fetcher);
  if (error) return <p>加载失败</p>;
  if (isLoading) return <p>加载中…</p>;
  return <ul>{data.map((a) => <li key={a.id}>{a.title}</li>)}</ul>;
}
